def para(txt,style='body'):
 return Paragraph(txt,ST[style])

def draw_footer(c,n,total,ch):
 left=64 if n%2 else 48
 c.setStrokeColor(LINE);c.line(left,45,left+CW,45)
 c.setFont('Body',7);c.setFillColor(GREY);c.drawString(left,31,'NUERS 1.0.0  |  Technical Specifications & System Manual')
 c.drawRightString(left+CW,31,f'{n:02d} / {total:02d}')
 c.setFont('Body',6.5);c.drawString(left,20,'19 OCT 2026  •  Controlled reference  •  Planned hosting and service targets require approval')

def draw_content(c,n,total,data):
 x=64 if n%2 else 48; y=PH-58
 c.setFillColor(BLUE);c.setFont('Bold',8);c.drawString(x,y,data['ch'].upper())
 c.drawImage(str(ROOT/'public/auth-assets/nuers-digital-logo.png'),x+CW-87,y-6,width=87,height=35,mask='auto',preserveAspectRatio=True)
 y-=38
 title=Paragraph(data['title'],ParagraphStyle('title',fontName='Bold',fontSize=23,leading=29,textColor=NAVY))
 _,hh=title.wrap(CW,100);title.drawOn(c,x,y-hh+24);y-=hh-14
 dek=para(data['dek'],'small');_,hh=dek.wrap(CW,100);dek.drawOn(c,x,y-hh);y-=hh+16
 c.setStrokeColor(BLUE);c.setLineWidth(2);c.line(x,y,x+33,y);y-=18
 for item in data['items']:
  typ=item[0]
  if typ in ('p','h'):
   q=para(item[1], 'h' if typ=='h' else 'body');y-=7 if typ=='h' else 0
   _,hh=q.wrap(CW,1000);q.drawOn(c,x,y-hh);y-=hh+(7 if typ=='h' else 11)
  elif typ=='note':
   q=para(item[1],'small');_,hh=q.wrap(CW-24,1000)
   c.setFillColor(PALE);c.roundRect(x,y-hh-20,CW,hh+16,5,fill=1,stroke=0)
   c.setFillColor(BLUE);c.rect(x,y-hh-20,3,hh+16,fill=1,stroke=0)
   q.drawOn(c,x+12,y-hh-11);y-=hh+22
  elif typ=='bullets':
   for row in item[1]:
    q=para(row);_,hh=q.wrap(CW-15,1000);c.setFillColor(BLUE);c.circle(x+3,y-6,2,fill=1,stroke=0);q.drawOn(c,x+15,y-hh);y-=hh+9
  elif typ=='table':
   _,heads,rows,widths=item
   widths=[CW*v for v in widths] if widths else [CW/len(heads)]*len(heads)
   grid=[[para(v,'thead') for v in heads]]+[[para(str(v),'cell') for v in row] for row in rows]
   t=Table(grid,colWidths=widths,hAlign='LEFT')
   t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),NAVY),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),9),('RIGHTPADDING',(0,0),(-1,-1),9),('TOPPADDING',(0,0),(-1,-1),7),('BOTTOMPADDING',(0,0),(-1,-1),7),('ROWBACKGROUNDS',(0,1),(-1,-1),[white,HexColor('#f3f7fc')]),('LINEBELOW',(0,0),(-1,-1),.4,LINE)]))
   _,hh=t.wrap(CW,1000);t.drawOn(c,x,y-hh);y-=hh+14
  elif typ=='diagram':
   d=Diagram(item[1]);d.drawOn(c,x,y-d.height);y-=d.height+9
   q=para(item[2],'small');_,hh=q.wrap(CW,1000);q.drawOn(c,x,y-hh);y-=hh+10
  if y<60:raise RuntimeError(f'Page {n} overflow after {typ}: bottom={y:.1f} ({data["title"]})')
 draw_footer(c,n,total,data['ch'])
 return y

def build():
 # Cover + two navigation pages precede the authored body.
 total=len(PAGES)+3; raw=TMP/'manual-unoptimized.pdf'
 c=canvas.Canvas(str(raw),pagesize=A4,pageCompression=1)
 c.setTitle('NUERS Technical Specifications and System Manual | Version 1.0.0')
 c.setAuthor('NUERS');c.setSubject('Architecture, data lineage, planned hosting, security, incident response and service-level framework')
 c.setCreator('NUERS controlled technical documentation')
 c.bookmarkPage('cover');c.addOutlineEntry('Cover','cover',0)
 c.setFillColor(NAVY);c.rect(0,0,PW,PH,fill=1,stroke=0)
 c.drawImage(str(ROOT/'public/auth-assets/nuers-digital-white.png'),52,PH-119,width=195,height=73,mask='auto',preserveAspectRatio=True)
 c.setFillColor(GOLD);c.rect(52,PH-145,45,4,fill=1,stroke=0)
 c.setFont('Bold',9);c.setFillColor(HexColor('#9fc8ff'));c.drawString(52,PH-172,'NATIONAL UNIFIED ELECTRONIC RECEIPT SYSTEM')
 for text,y in [('Technical Specifications',PH-218),('& System Manual',PH-257)]:
  c.setFont('Bold',28);c.setFillColor(white);c.drawString(52,y,text)
 c.setFont('Body',11);c.setFillColor(HexColor('#c2d8f6'));c.drawString(52,PH-290,'Architecture • Security • Operations • Service Framework')
 c.drawImage(str(ROOT/'output/technical-manual/assets/secure-transaction-architecture.png'),0,196,width=PW,height=335,mask='auto')
 c.setFillColor(NAVY);c.rect(0,0,PW,180,fill=1,stroke=0)
 c.setFont('Bold',12);c.setFillColor(white);c.drawString(52,151,'SOFTWARE VERSION 1.0.0')
 c.setFont('Body',10);c.setFillColor(HexColor('#c2d8f6'));c.drawString(52,130,'Manual edition 1.0  |  19 October 2026')
 q=Paragraph('Implementation baseline and proposed operating plan.<br/>Dataplugs, Contabo and AWS Singapore / Hong Kong are planned providers and regions, not a deployed architecture claim.',ParagraphStyle('covernote',fontName='Body',fontSize=9,leading=14,textColor=HexColor('#c2d8f6')))
 _,hh=q.wrap(PW-104,100);q.drawOn(c,52,65)
 c.setFillColor(BLUE);c.rect(52,42,250,4,fill=1,stroke=0);c.setFillColor(GOLD);c.rect(302,42,45,4,fill=1,stroke=0);c.setFillColor(HexColor('#e5233c'));c.rect(347,42,40,4,fill=1,stroke=0)
 c.showPage()
 for index,subset in enumerate([PAGES[:len(PAGES)//2],PAGES[len(PAGES)//2:]]):
  n=2+index;x=48 if n%2==0 else 64;c.bookmarkPage('contents'+str(index));c.addOutlineEntry('Contents '+str(index+1),'contents'+str(index),0)
  c.setFillColor(BLUE);c.setFont('Bold',8);c.drawString(x,PH-58,'NAVIGATION  |  CLICK A TITLE TO OPEN ITS PAGE')
  c.setFont('Bold',25);c.setFillColor(NAVY);c.drawString(x,PH-100,'Contents' if index==0 else 'Contents / continued')
  y=PH-138;start=0 if index==0 else len(PAGES)//2
  for j,data in enumerate(subset,start=start):
   page_no=j+4; title=data['title']; c.setFont('Body',9);c.setFillColor(INK)
   c.drawString(x,y,title);c.setFillColor(BLUE);c.drawRightString(x+CW,y,str(page_no))
   c.linkRect('',f'p{page_no}',(x,y-4,x+CW,y+12),relative=0,thickness=0)
   c.setStrokeColor(LINE);c.setLineWidth(.4);c.line(x,y-8,x+CW,y-8);y-=24
  draw_footer(c,n,total,'Contents');c.showPage()
 metrics=[];lastch=None
 for i,data in enumerate(PAGES,4):
  c.bookmarkPage('p'+str(i))
  if data['ch']!=lastch:c.addOutlineEntry(data['ch'],'p'+str(i),0);lastch=data['ch']
  c.addOutlineEntry(data['title'],'p'+str(i),1)
  bottom=draw_content(c,i,total,data);metrics.append({'page':i,'title':data['title'],'bottom':round(bottom,1)})
  c.showPage()
 c.save()
 reader=PdfReader(raw);writer=PdfWriter();writer.clone_document_from_reader(reader)
 writer.pdf_header='%PDF-1.7'
 writer.root_object[NameObject('/ViewerPreferences')]=DictionaryObject({NameObject('/DisplayDocTitle'):BooleanObject(True),NameObject('/PrintScaling'):NameObject('/None'),NameObject('/Duplex'):NameObject('/DuplexFlipLongEdge')})
 for pge in writer.pages:pge.compress_content_streams()
 for _ in range(3):writer.compress_identical_objects(remove_duplicates=True,remove_unreferenced=True)
 with OUT.open('wb') as f:writer.write(f)
 text='\n'.join(pg.extract_text() for pg in PdfReader(OUT).pages)
 assert len(PdfReader(OUT).pages)==total
 required=['Data-lineage diagram','Dataplugs','Contabo','ap-southeast-1','ap-east-1','Incident command','Service catalogue','1.0.0']
 assert all(v in text for v in required)
 (TMP/'layout-metrics.json').write_text(json.dumps(metrics,indent=2))
 (TMP/'extracted-text.txt').write_text(text)
 (TMP/'validation.json').write_text(json.dumps({'pages':total,'bytes':OUT.stat().st_size,'words':len(text.split()),'minimum_bottom':min(m['bottom'] for m in metrics),'sha256':hashlib.sha256(OUT.read_bytes()).hexdigest()},indent=2))
 print(json.dumps({'pdf':str(OUT),'pages':total,'bytes':OUT.stat().st_size,'words':len(text.split()),'minimum_bottom':min(m['bottom'] for m in metrics)}))

if __name__=='__main__':build()
